-- Profiles
create policy profiles_read on public.profiles for select to authenticated using (public.can_see_profile(id));
create policy profiles_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- Catalog: readable by everyone, written by admins. Coaches may add their own variations.
create policy disciplines_read on public.disciplines for select to anon, authenticated using (true);
create policy exercises_read on public.exercises for select to anon, authenticated using (true);
create policy progressions_read on public.progressions for select to anon, authenticated using (true);
create policy progression_steps_read on public.progression_steps for select to anon, authenticated using (true);
create policy skills_read on public.skills for select to anon, authenticated using (true);
create policy skill_prerequisites_read on public.skill_prerequisites for select to anon, authenticated using (true);
create policy scoring_models_read on public.scoring_models for select to anon, authenticated using (true);
create policy rating_curves_read on public.rating_curves for select to anon, authenticated using (true);
create policy workouts_read on public.workouts for select to anon, authenticated using (true);
create policy workout_items_read on public.workout_items for select to anon, authenticated using (true);
create policy achievements_read on public.achievements for select to anon, authenticated using (true);

create policy disciplines_admin on public.disciplines for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy skills_admin on public.skills for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy skill_prerequisites_admin on public.skill_prerequisites for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy scoring_models_admin on public.scoring_models for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy rating_curves_admin on public.rating_curves for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy workouts_admin on public.workouts for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy workout_items_admin on public.workout_items for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));
create policy achievements_admin on public.achievements for all to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));

create policy exercises_write on public.exercises for all to authenticated
  using (public.has_role('admin') or (created_by = auth.uid() and public.has_role('coach')))
  with check (public.has_role('admin') or (created_by = auth.uid() and public.has_role('coach')));
create policy progressions_write on public.progressions for all to authenticated
  using (public.has_role('admin') or (created_by = auth.uid() and public.has_role('coach')))
  with check (public.has_role('admin') or (created_by = auth.uid() and public.has_role('coach')));
create policy progression_steps_write on public.progression_steps for all to authenticated
  using (public.has_role('admin') or exists (select 1 from public.progressions p where p.id = progression_id and p.created_by = auth.uid()))
  with check (public.has_role('admin') or exists (select 1 from public.progressions p where p.id = progression_id and p.created_by = auth.uid()));

create policy exercise_media_read on public.exercise_media for select to authenticated using (true);
create policy exercise_media_write on public.exercise_media for all to authenticated
  using (coach_id = auth.uid() and public.has_role('coach'))
  with check (coach_id = auth.uid() and public.has_role('coach'));

-- Courses
create policy courses_read on public.courses for select to authenticated using (public.can_see_course(id));
create policy courses_write on public.courses for all to authenticated
  using (coach_id = auth.uid() and public.has_role('coach'))
  with check (coach_id = auth.uid() and public.has_role('coach'));

create policy course_milestones_read on public.course_milestones for select to authenticated using (public.can_see_course(course_id));
create policy course_milestones_write on public.course_milestones for all to authenticated
  using (public.coaches_course(course_id)) with check (public.coaches_course(course_id));

create policy course_weeks_read on public.course_weeks for select to authenticated using (public.can_see_course(course_id));
create policy course_weeks_write on public.course_weeks for all to authenticated
  using (public.coaches_course(course_id)) with check (public.coaches_course(course_id));

create policy course_sessions_read on public.course_sessions for select to authenticated using (public.can_see_course(public.week_course(week_id)));
create policy course_sessions_write on public.course_sessions for all to authenticated
  using (public.coaches_course(public.week_course(week_id))) with check (public.coaches_course(public.week_course(week_id)));

create policy course_blocks_read on public.course_blocks for select to authenticated using (public.can_see_course(public.session_course(session_id)));
create policy course_blocks_write on public.course_blocks for all to authenticated
  using (public.coaches_course(public.session_course(session_id))) with check (public.coaches_course(public.session_course(session_id)));

-- Enrolment: athletes join active courses themselves; coaches manage their own rosters.
create policy enrollments_read on public.course_enrollments for select to authenticated
  using (athlete_id = auth.uid() or public.coaches_course(course_id));
create policy enrollments_join on public.course_enrollments for insert to authenticated
  with check (
    public.coaches_course(course_id)
    or (athlete_id = auth.uid() and exists (select 1 from public.courses c where c.id = course_id and c.status = 'active'))
  );
create policy enrollments_update on public.course_enrollments for update to authenticated
  using (athlete_id = auth.uid() or public.coaches_course(course_id))
  with check (athlete_id = auth.uid() or public.coaches_course(course_id));
create policy enrollments_leave on public.course_enrollments for delete to authenticated
  using (athlete_id = auth.uid() or public.coaches_course(course_id));

-- Workout logs: the athlete, plus the coach of the course the log belongs to.
create policy logs_read on public.workout_logs for select to authenticated
  using (athlete_id = auth.uid() or (course_id is not null and public.coaches_course(course_id)));
create policy logs_insert on public.workout_logs for insert to authenticated with check (athlete_id = auth.uid());
create policy logs_update on public.workout_logs for update to authenticated using (athlete_id = auth.uid()) with check (athlete_id = auth.uid());
create policy logs_delete on public.workout_logs for delete to authenticated using (athlete_id = auth.uid());

create policy log_entries_read on public.workout_log_entries for select to authenticated using (public.can_read_log(log_id));
create policy log_entries_write on public.workout_log_entries for all to authenticated
  using (public.owns_log(log_id)) with check (public.owns_log(log_id));

create policy log_sets_read on public.workout_log_sets for select to authenticated
  using (exists (select 1 from public.workout_log_entries e where e.id = entry_id and public.can_read_log(e.log_id)));
create policy log_sets_write on public.workout_log_sets for all to authenticated
  using (exists (select 1 from public.workout_log_entries e where e.id = entry_id and public.owns_log(e.log_id)))
  with check (exists (select 1 from public.workout_log_entries e where e.id = entry_id and public.owns_log(e.log_id)));

-- Evidence: athletes add estimated or self-reported records only, and cannot edit them.
-- Verification happens through verify_evidence().
create policy evidence_read on public.evidence for select to authenticated
  using (athlete_id = auth.uid() or public.coaches_athlete(athlete_id));
create policy evidence_insert on public.evidence for insert to authenticated
  with check (athlete_id = auth.uid() and tier in ('estimated', 'self') and verified_by is null and verified_at is null);
create policy evidence_delete on public.evidence for delete to authenticated
  using (athlete_id = auth.uid() and tier in ('estimated', 'self'));

-- Feedback: written by the coach of the log's course, read by both sides.
create policy feedback_read on public.feedback for select to authenticated using (athlete_id = auth.uid() or coach_id = auth.uid());
create policy feedback_insert on public.feedback for insert to authenticated
  with check (
    coach_id = auth.uid()
    and exists (select 1 from public.workout_logs wl where wl.id = log_id and wl.athlete_id = feedback.athlete_id and wl.course_id is not null and public.coaches_course(wl.course_id))
  );
create policy feedback_delete on public.feedback for delete to authenticated using (coach_id = auth.uid());

create policy goals_read on public.athlete_goals for select to authenticated using (public.can_see_profile(athlete_id));
create policy goals_write on public.athlete_goals for all to authenticated using (athlete_id = auth.uid()) with check (athlete_id = auth.uid());

-- Snapshots: visible wherever the profile is. No client write policies: the scoring
-- job runs with the service role, so a score can never be set by hand.
create policy mastery_ratings_read on public.mastery_ratings for select to authenticated using (public.can_see_profile(athlete_id));
create policy aura_records_read on public.aura_records for select to authenticated using (public.can_see_profile(athlete_id));
create policy skill_achievements_read on public.skill_achievements for select to authenticated using (public.can_see_profile(athlete_id));
create policy athlete_achievements_read on public.athlete_achievements for select to authenticated using (public.can_see_profile(athlete_id));

create policy follows_read on public.follows for select to authenticated using (true);
create policy follows_write on public.follows for all to authenticated using (follower_id = auth.uid()) with check (follower_id = auth.uid());

-- ── Grants (RLS above decides the rows) ──────────────────────────────────

grant usage on schema public to anon, authenticated;
grant select on public.disciplines, public.exercises, public.progressions, public.progression_steps, public.skills,
  public.skill_prerequisites, public.scoring_models, public.rating_curves, public.workouts, public.workout_items,
  public.achievements to anon;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant execute on all functions in schema public to authenticated;
revoke execute on function public.handle_new_user() from authenticated, anon;
revoke execute on function public.protect_profile_roles() from authenticated, anon;


-- ════════════════════════════════════════════════════════════════════════
-- 0002_storage.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · media storage
--
-- Demonstration videos uploaded by coaches. Requires Supabase's storage schema,
-- so this file is applied by Supabase only (the local schema check skips it).

insert into storage.buckets (id, name, public)
values ('demonstrations', 'demonstrations', true)
on conflict (id) do nothing;

-- Anyone can watch a demonstration.
create policy demonstrations_read on storage.objects for select to anon, authenticated
  using (bucket_id = 'demonstrations');

-- Coaches upload into a folder named after their own user id.
create policy demonstrations_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'demonstrations' and public.has_role('coach') and (storage.foldername(name))[1] = auth.uid()::text);

create policy demonstrations_manage on storage.objects for delete to authenticated
  using (bucket_id = 'demonstrations' and (storage.foldername(name))[1] = auth.uid()::text);


-- ════════════════════════════════════════════════════════════════════════
-- 0003_evidence_observed.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · a third way of knowing
--
-- 'observed': a coach was present and watched, without checking it against the
-- written standard. It ranks above self-reported and below coach-verified.
-- A new enum value cannot be used in the transaction that adds it, so this
-- lives in its own migration.

alter type public.evidence_tier add value if not exists 'observed' before 'coach';


-- ════════════════════════════════════════════════════════════════════════
-- 0004_assessments.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · assessments
--
-- A session is one assessment event: a coach's group session or an athlete
-- testing alone. People join a group session with its invitation token, never
-- by browsing. Individual results are visible to the athlete and the session's
-- coach only; the rest of the group sees anonymous totals, plus the shape of
-- anyone who chose to share it.

-- ── Evidence learns about observation and assessments ────────────────────

alter table public.evidence add column observed_by uuid references public.profiles (id) on delete set null;
alter table public.evidence add column assessment_id uuid;
alter table public.evidence drop constraint evidence_source_check;
alter table public.evidence add constraint evidence_source_check check (source in ('onboarding', 'workout', 'manual', 'assessment'));
alter table public.evidence add constraint evidence_observed_check check (tier <> 'observed' or observed_by is not null);

alter table public.mastery_ratings drop constraint mastery_ratings_status_check;
alter table public.mastery_ratings add constraint mastery_ratings_status_check check (status in ('unrated', 'estimated', 'self', 'observed', 'verified'));
alter table public.aura_records drop constraint aura_records_status_check;
alter table public.aura_records add constraint aura_records_status_check check (status in ('unrated', 'estimated', 'self', 'observed', 'verified'));

-- ── Tables ───────────────────────────────────────────────────────────────

create table public.assessment_sessions (
  id uuid primary key default gen_random_uuid(),
  -- The coach of a group session, or the athlete of a solo one.
  owner_id uuid not null references public.profiles (id) on delete cascade,
  solo boolean not null default false,
  protocol text not null,
  kind text not null default 'baseline' check (kind in ('baseline', 'retest')),
  title text not null default 'Baseline',
  group_name text not null default '',
  course_id uuid references public.courses (id) on delete set null,
  baseline_id uuid references public.assessment_sessions (id) on delete set null,
  stations text[] not null check (cardinality(stations) > 0),
  status text not null default 'open' check (status in ('open', 'finalised')),
  station_minutes smallint not null default 6,
  rotation_started_at timestamptz,
  -- What the QR code carries. Unguessable, revocable, and optionally short-lived.
  invite_token text not null unique default replace(gen_random_uuid()::text, '-', ''),
  invite_expires_at timestamptz,
  created_at timestamptz not null default now(),
  finalised_at timestamptz
);

alter table public.evidence add constraint evidence_assessment_fk foreign key (assessment_id) references public.assessment_sessions (id) on delete set null;

create table public.assessment_participants (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.assessment_sessions (id) on delete cascade,
  -- Null for someone the coach added by name who has no account yet.
  athlete_id uuid references public.profiles (id) on delete cascade,
  display_name text not null,
  sharing text not null default 'coach' check (sharing in ('coach', 'group')),
  partner_name text,
  skipped text[] not null default '{}',
  flags text[] not null default '{}',
  joined_at timestamptz not null default now(),
  submitted_at timestamptz,
  unique (session_id, athlete_id)
);

create table public.assessment_results (
  participant_id uuid not null references public.assessment_participants (id) on delete cascade,
  test_id text not null,
  value integer not null check (value >= 0),
  skipped boolean not null default false,
  tier public.evidence_tier not null default 'self' check (tier in ('self', 'observed', 'coach')),
  -- What this result shows, as [[exercise_id, value], ...]. The protocol lives in the app.
  demonstrates jsonb not null default '[]',
  recorded_by uuid references public.profiles (id) on delete set null,
  recorded_at timestamptz not null default now(),
  primary key (participant_id, test_id)
);

-- The six ratings an assessment produced. This is what the group may see of a
-- member: a shape, not their individual results.
create table public.assessment_profiles (
  participant_id uuid primary key references public.assessment_participants (id) on delete cascade,
  ratings jsonb not null,
  aura integer not null default 0,
  computed_at timestamptz not null default now()
);

create index assessment_sessions_owner on public.assessment_sessions (owner_id, created_at desc);
create index assessment_participants_session on public.assessment_participants (session_id);
create index assessment_participants_athlete on public.assessment_participants (athlete_id);

-- ── Helpers ──────────────────────────────────────────────────────────────

create function public.owns_assessment(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.assessment_sessions where id = s and owner_id = auth.uid());
$$;

create function public.in_assessment(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.assessment_participants where session_id = s and athlete_id = auth.uid());
$$;

create function public.participant_session(p uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select session_id from public.assessment_participants where id = p;
$$;

create function public.is_my_participant(p uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.assessment_participants where id = p and athlete_id = auth.uid());
$$;

create function public.assessment_open(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.assessment_sessions where id = s and status = 'open');
$$;

-- Joining is the only thing an invitation token allows, and the only way in.
create function public.join_assessment(token text, share text default 'coach') returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s public.assessment_sessions;
begin
  select * into s from public.assessment_sessions where invite_token = token;
  if s.id is null or s.solo or s.status <> 'open' or (s.invite_expires_at is not null and s.invite_expires_at < now()) then
    raise exception 'this invitation is not valid';
  end if;
  insert into public.assessment_participants (session_id, athlete_id, display_name, sharing)
  select s.id, auth.uid(), p.name, case when share = 'group' then 'group' else 'coach' end from public.profiles p where p.id = auth.uid()
  on conflict (session_id, athlete_id) do update set sharing = excluded.sharing;
  return s.id;
end;
$$;

-- A coach says how well they know a result. Never on their own results.
create function public.set_result_tier(p uuid, test text, new_tier public.evidence_tier) returns void
language plpgsql security definer set search_path = public as $$
begin
  if new_tier::text not in ('self', 'observed', 'coach') then
    raise exception 'tier must be self, observed or coach';
  end if;
  if not public.owns_assessment(public.participant_session(p)) or public.is_my_participant(p) then
    raise exception 'only the coach of this assessment can observe or verify a result';
  end if;
  update public.assessment_results set tier = new_tier where participant_id = p and test_id = test and not skipped;
end;
$$;

-- What the group may see of itself: one anonymous row of ratings per finished
-- member, and nothing at all until there are enough people to hide in.
create function public.assessment_group(s uuid) returns table (ratings jsonb, aura integer)
language sql stable security definer set search_path = public as $$
  select pr.ratings, pr.aura
  from public.assessment_profiles pr
  join public.assessment_participants p on p.id = pr.participant_id
  where p.session_id = s
    and (public.owns_assessment(s) or public.in_assessment(s))
    and (public.owns_assessment(s) or (select count(*) from public.assessment_profiles x join public.assessment_participants y on y.id = x.participant_id where y.session_id = s) >= 3);
$$;

-- Closing a session turns its results into evidence, each at the tier it was
-- given, and puts every participant with an account into the linked course.
create function public.finalise_assessment(s uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  session public.assessment_sessions;
begin
  select * into session from public.assessment_sessions where id = s;
  if session.id is null or session.owner_id <> auth.uid() then
    raise exception 'only the owner can finalise an assessment';
  end if;
  update public.assessment_sessions set status = 'finalised', finalised_at = now() where id = s;

  delete from public.evidence where assessment_id = s;
  insert into public.evidence (athlete_id, exercise_id, value, tier, source, assessment_id, observed_by, verified_by, verified_at, performed_at)
  select p.athlete_id, d ->> 0, (d ->> 1)::int,
         case when p.athlete_id = session.owner_id then 'self' else r.tier end,
         'assessment', s,
         case when r.tier = 'observed' and p.athlete_id <> session.owner_id then session.owner_id end,
         case when r.tier = 'coach' and p.athlete_id <> session.owner_id then session.owner_id end,
         case when r.tier = 'coach' and p.athlete_id <> session.owner_id then now() end,
         r.recorded_at
  from public.assessment_participants p
  join public.assessment_results r on r.participant_id = p.id
  cross join lateral jsonb_array_elements(r.demonstrates) d
  where p.session_id = s and p.athlete_id is not null and not r.skipped and (d ->> 1)::int > 0;

  if session.course_id is not null and public.coaches_course(session.course_id) then
    insert into public.course_enrollments (course_id, athlete_id)
    select session.course_id, p.athlete_id from public.assessment_participants p
    where p.session_id = s and p.athlete_id is not null and p.athlete_id <> session.owner_id
    on conflict (course_id, athlete_id) do nothing;
  end if;
end;
$$;

-- ── Row level security ───────────────────────────────────────────────────

alter table public.assessment_sessions enable row level security;
alter table public.assessment_participants enable row level security;
alter table public.assessment_results enable row level security;
alter table public.assessment_profiles enable row level security;

create policy assessment_sessions_read on public.assessment_sessions for select to authenticated
  using (owner_id = auth.uid() or public.in_assessment(id));
create policy assessment_sessions_insert on public.assessment_sessions for insert to authenticated
  with check (owner_id = auth.uid() and (solo or public.has_role('coach')) and (course_id is null or public.coaches_course(course_id)));
create policy assessment_sessions_update on public.assessment_sessions for update to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy assessment_sessions_delete on public.assessment_sessions for delete to authenticated using (owner_id = auth.uid());

-- Members see who else is in the group only when that person chose to be seen.
create policy assessment_participants_read on public.assessment_participants for select to authenticated
  using (athlete_id = auth.uid() or public.owns_assessment(session_id) or (sharing = 'group' and public.in_assessment(session_id)));
create policy assessment_participants_insert on public.assessment_participants for insert to authenticated
  with check (public.owns_assessment(session_id));
create policy assessment_participants_update on public.assessment_participants for update to authenticated
  using (athlete_id = auth.uid() or public.owns_assessment(session_id))
  with check (athlete_id = auth.uid() or public.owns_assessment(session_id));
create policy assessment_participants_delete on public.assessment_participants for delete to authenticated
  using (athlete_id = auth.uid() or public.owns_assessment(session_id));

-- Results: the athlete and the coach. Nobody else in the group, ever.
create policy assessment_results_read on public.assessment_results for select to authenticated
  using (public.is_my_participant(participant_id) or public.owns_assessment(public.participant_session(participant_id)));
-- An athlete records their own results as self-reported, while the session is open.
create policy assessment_results_self on public.assessment_results for all to authenticated
  using (public.is_my_participant(participant_id) and public.assessment_open(public.participant_session(participant_id)))
  with check (public.is_my_participant(participant_id) and tier = 'self' and public.assessment_open(public.participant_session(participant_id)));
-- A coach records for the people they are watching; that starts as observed.
create policy assessment_results_coach on public.assessment_results for all to authenticated
  using (public.owns_assessment(public.participant_session(participant_id)) and not public.is_my_participant(participant_id))
  with check (public.owns_assessment(public.participant_session(participant_id)) and not public.is_my_participant(participant_id) and recorded_by = auth.uid());

create policy assessment_profiles_read on public.assessment_profiles for select to authenticated
  using (
    public.is_my_participant(participant_id)
    or public.owns_assessment(public.participant_session(participant_id))
    or exists (select 1 from public.assessment_participants p where p.id = participant_id and p.sharing = 'group' and public.in_assessment(p.session_id))
  );
create policy assessment_profiles_write on public.assessment_profiles for all to authenticated
  using (public.is_my_participant(participant_id) or public.owns_assessment(public.participant_session(participant_id)))
  with check (public.is_my_participant(participant_id) or public.owns_assessment(public.participant_session(participant_id)));

grant select, insert, update, delete on public.assessment_sessions, public.assessment_participants, public.assessment_results, public.assessment_profiles to authenticated;
grant execute on function public.owns_assessment(uuid), public.in_assessment(uuid), public.participant_session(uuid), public.is_my_participant(uuid),
  public.assessment_open(uuid), public.join_assessment(text, text), public.set_result_tier(uuid, text, public.evidence_tier),
  public.assessment_group(uuid), public.finalise_assessment(uuid) to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0005_places.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · identity, places and presence
--
-- Principles encoded here:
--   1. Where an athlete is, is never stored. A visit records a place and a time window.
--      Coordinates may be passed once to check_in() to confirm "on site" and are discarded.
--   2. Every visit ends. There is no open-ended presence (4 hours at most), and a new
--      check-in ends the one before it.
--   3. Four relationships to a place stay separate: a running visit, visit history,
--      a declared favourite, a declared home spot. Each has its own audience.
--   4. "following" means the people the OWNER follows, a list the owner controls.
--   5. None of this is an input to any rating.

create type public.audience as enum ('me', 'following', 'everyone');
create type public.place_kind as enum ('calisthenics', 'outdoor', 'gym', 'studio', 'other');

-- ── Places ───────────────────────────────────────────────────────────────

create table public.places (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 80),
  kind public.place_kind not null,
  lat double precision not null check (lat between -90 and 90),
  lon double precision not null check (lon between -180 and 180),
  address text,
  equipment text[] not null default '{}',
  amenities text[] not null default '{}',
  access text check (access in ('free', 'members')),
  hours text,
  note text check (note is null or length(note) <= 500),
  -- osm: imported from OpenStreetMap (service role only) · athlete: added by a person
  source text not null check (source in ('osm', 'athlete')),
  -- OpenStreetMap element, as "node/123". One place per element.
  osm_ref text unique,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((source = 'osm') = (osm_ref is not null))
);

create index places_position on public.places (lat, lon);

-- "I was here and the details are right." Only possible during a visit.
create table public.place_confirmations (
  place_id uuid not null references public.places (id) on delete cascade,
  athlete_id uuid not null references public.profiles (id) on delete cascade,
  confirmed_at timestamptz not null default now(),
  primary key (place_id, athlete_id)
);

-- ── Identity beyond ability ──────────────────────────────────────────────

-- Kept apart from profiles so that each part can have its own audience:
-- a profile row is readable as a whole by anyone who may see the profile.
create table public.athlete_identity (
  athlete_id uuid primary key references public.profiles (id) on delete cascade,
  origin text check (origin is null or length(origin) <= 80),
  city text check (city is null or length(city) <= 80),
  environments text[] not null default '{}' check (environments <@ array['outdoor', 'gym', 'studio', 'home']),
  home_place_id uuid references public.places (id) on delete set null,
  open_to_train boolean not null default false,
  origin_audience public.audience not null default 'everyone',
  base_audience public.audience not null default 'everyone',
  -- Declared places: home spot, favourites, preferred environments.
  places_audience public.audience not null default 'following',
  -- Derived from behaviour: visit history and "regular" status. Closed unless opened.
  visits_audience public.audience not null default 'me',
  updated_at timestamptz not null default now()
);

-- The city moves here so it can have an audience of its own.
insert into public.athlete_identity (athlete_id, city) select id, city from public.profiles where city is not null;
alter table public.profiles drop column city;

create table public.place_favourites (
  athlete_id uuid not null references public.profiles (id) on delete cascade,
  place_id uuid not null references public.places (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (athlete_id, place_id)
);

-- ── Presence ─────────────────────────────────────────────────────────────

create table public.visits (
  id uuid primary key default gen_random_uuid(),
  athlete_id uuid not null references public.profiles (id) on delete cascade,
  place_id uuid not null references public.places (id) on delete cascade,
  started_at timestamptz not null default now(),
  ends_at timestamptz not null,
  audience public.audience not null default 'me',
  -- The server compared a position supplied at check-in with the place, once.
  on_site boolean not null default false,
  check (ends_at >= started_at and ends_at <= started_at + interval '4 hours')
);

create index visits_place_time on public.visits (place_id, ends_at desc);
create index visits_athlete_time on public.visits (athlete_id, started_at desc);

alter table public.workout_logs add column place_id uuid references public.places (id) on delete set null;

-- ── Helpers ──────────────────────────────────────────────────────────────

-- Does `owner` follow the caller? That is what opens a "following" audience.
create function public.follows_me(owner uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.follows where follower_id = owner and followee_id = auth.uid());
$$;

create function public.audience_allows(a public.audience, owner uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select owner = auth.uid() or a = 'everyone' or (a = 'following' and public.follows_me(owner));
$$;

create function public.metres_between(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
returns double precision language sql immutable as $$
  select 2 * 6371000 * asin(least(1, sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lon2 - lon1) / 2), 2)
  )));
$$;

-- A running visit is shown to its audience. A finished one also needs the
-- owner to have opened their visit history to that audience.
create function public.can_see_visit(owner uuid, a public.audience, starts timestamptz, ends timestamptz) returns boolean
language sql stable security definer set search_path = public as $$
  select owner = auth.uid()
      or (public.audience_allows(a, owner)
          and ((starts <= now() and now() < ends)
               or public.audience_allows(coalesce((select visits_audience from public.athlete_identity where athlete_id = owner), 'me'), owner)));
$$;

-- An athlete's identity as the caller is allowed to see it. Hidden parts come back null.
create function public.identity_of(p uuid)
returns table (origin text, city text, environments text[], home_place_id uuid, favourite_place_ids uuid[], open_to_train boolean)
language sql stable security definer set search_path = public as $$
  select
    case when public.audience_allows(i.origin_audience, p) then i.origin end,
    case when public.audience_allows(i.base_audience, p) then i.city end,
    case when public.audience_allows(i.places_audience, p) then i.environments else '{}' end,
    case when public.audience_allows(i.places_audience, p) then i.home_place_id end,
    case when public.audience_allows(i.places_audience, p)
      then coalesce((select array_agg(f.place_id order by f.created_at) from public.place_favourites f where f.athlete_id = p), '{}')
      else '{}' end,
    i.open_to_train
  from public.athlete_identity i
  where i.athlete_id = p and public.can_see_profile(p);
$$;

-- The only way to start a visit. `at_lat`/`at_lon` are optional, used for one
-- comparison and never written anywhere.
create function public.check_in(
  p_place uuid, p_minutes integer default 90, p_audience public.audience default 'me',
  at_lat double precision default null, at_lon double precision default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  pl public.places;
  v uuid;
  t timestamptz := now();
begin
  if me is null then raise exception 'sign in to check in'; end if;
  select * into pl from public.places where id = p_place;
  if pl.id is null then raise exception 'unknown place'; end if;
  -- Nobody is in two places: whatever is still running ends now.
  update public.visits set ends_at = t where athlete_id = me and ends_at > t;
  insert into public.visits (athlete_id, place_id, started_at, ends_at, audience, on_site)
  values (
    me, p_place, t, t + make_interval(mins => least(240, greatest(15, coalesce(p_minutes, 90)))), p_audience,
    at_lat is not null and at_lon is not null and public.metres_between(at_lat, at_lon, pl.lat, pl.lon) <= 200
  )
  returning id into v;
  return v;
end;
$$;

create function public.touch_place() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
create trigger places_touch before update on public.places for each row execute function public.touch_place();

-- A visit's owner may shorten or extend it and change who sees it. Nothing else.
create function public.protect_visit() returns trigger language plpgsql as $$
begin
  if new.athlete_id <> old.athlete_id or new.place_id <> old.place_id or new.started_at <> old.started_at or new.on_site <> old.on_site then
    raise exception 'only the end time and the audience of a visit can change';
  end if;
  return new;
end;
$$;
create trigger visits_protect before update on public.visits for each row execute function public.protect_visit();

-- ── Row level security ───────────────────────────────────────────────────

alter table public.places enable row level security;
alter table public.place_confirmations enable row level security;
alter table public.athlete_identity enable row level security;
alter table public.place_favourites enable row level security;
alter table public.visits enable row level security;

-- Places are public knowledge. People add their own; imports use the service role.
create policy places_read on public.places for select to anon, authenticated using (true);
create policy places_insert on public.places for insert to authenticated
  with check (source = 'athlete' and created_by = auth.uid());
create policy places_update on public.places for update to authenticated
  using ((source = 'athlete' and created_by = auth.uid()) or public.has_role('admin'))
  with check ((source = 'athlete' and created_by = auth.uid()) or public.has_role('admin'));
create policy places_delete on public.places for delete to authenticated
  using ((source = 'athlete' and created_by = auth.uid()) or public.has_role('admin'));

-- How many people vouch for a place is public; a confirmation needs a visit running there.
create policy confirmations_read on public.place_confirmations for select to authenticated using (true);
create policy confirmations_insert on public.place_confirmations for insert to authenticated
  with check (athlete_id = auth.uid() and exists (
    select 1 from public.visits v where v.athlete_id = auth.uid() and v.place_id = place_confirmations.place_id and v.started_at <= now() and now() < v.ends_at
  ));
create policy confirmations_delete on public.place_confirmations for delete to authenticated using (athlete_id = auth.uid());

-- The identity row itself is the owner's alone. Everyone else goes through identity_of().
create policy identity_own on public.athlete_identity for all to authenticated
  using (athlete_id = auth.uid()) with check (athlete_id = auth.uid());

create policy favourites_read on public.place_favourites for select to authenticated
  using (athlete_id = auth.uid() or public.audience_allows(
    coalesce((select places_audience from public.athlete_identity i where i.athlete_id = place_favourites.athlete_id), 'following'), athlete_id));
create policy favourites_write on public.place_favourites for all to authenticated
  using (athlete_id = auth.uid()) with check (athlete_id = auth.uid());

-- Visits start through check_in() only: there is no insert policy.
create policy visits_read on public.visits for select to authenticated
  using (public.can_see_visit(athlete_id, audience, started_at, ends_at));
create policy visits_update on public.visits for update to authenticated
  using (athlete_id = auth.uid()) with check (athlete_id = auth.uid());
create policy visits_delete on public.visits for delete to authenticated using (athlete_id = auth.uid());

grant select on public.places to anon;
grant select, insert, update, delete on public.places, public.place_confirmations, public.athlete_identity, public.place_favourites to authenticated;
grant select, update, delete on public.visits to authenticated;
revoke insert on public.visits from authenticated;
grant execute on function public.follows_me(uuid), public.audience_allows(public.audience, uuid),
  public.metres_between(double precision, double precision, double precision, double precision),
  public.can_see_visit(uuid, public.audience, timestamptz, timestamptz), public.identity_of(uuid),
  public.check_in(uuid, integer, public.audience, double precision, double precision) to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0006_live.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · going live
--
-- What the app needs once real people use one database from many phones:
--   1. An invitation can be read before signing in, and says only what the
--      join screen shows.
--   2. Joining an assessment puts the athlete in its course straight away.
--   3. Evidence an assessment wrote goes when the assessment, or the athlete's
--      part in it, goes.
--   4. A guest who already has an account can move a test day's results into it.
--   5. The assessment tables announce their changes, so a coach's board is live.
--
-- Safe to run on a project that already has 0001–0005. Run it once.

-- ── 1 · Reading an invitation ────────────────────────────────────────────

-- The token is the only way to learn anything about a session from outside
-- it, and this is all it tells: enough to decide whether to join.
create function public.peek_invite(token text)
returns table (session_id uuid, title text, group_name text, coach_name text, kind text, protocol text, stations text[], course_title text)
language sql stable security definer set search_path = public as $$
  select s.id, s.title, s.group_name, p.name, s.kind, s.protocol, s.stations, c.title
  from public.assessment_sessions s
  join public.profiles p on p.id = s.owner_id
  left join public.courses c on c.id = s.course_id
  where s.invite_token = token and not s.solo and s.status = 'open'
    and (s.invite_expires_at is null or s.invite_expires_at > now());
$$;

-- ── 2 · Joining enrols ───────────────────────────────────────────────────

-- As before, plus: the course an assessment belongs to is joined with it, so
-- the group is one pool from the first scan rather than from finalising.
create or replace function public.join_assessment(token text, share text default 'coach') returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s public.assessment_sessions;
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'sign in to join';
  end if;
  select * into s from public.assessment_sessions where invite_token = token;
  if s.id is null or s.solo or s.status <> 'open' or (s.invite_expires_at is not null and s.invite_expires_at < now()) then
    raise exception 'this invitation is not valid';
  end if;
  insert into public.profiles (id) values (me) on conflict (id) do nothing;
  insert into public.assessment_participants (session_id, athlete_id, display_name, sharing)
  select s.id, me, p.name, case when share = 'group' then 'group' else 'coach' end from public.profiles p where p.id = me
  on conflict (session_id, athlete_id) do update set sharing = excluded.sharing, display_name = excluded.display_name;
  if s.course_id is not null and me <> s.owner_id then
    insert into public.course_enrollments (course_id, athlete_id) values (s.course_id, me)
    on conflict (course_id, athlete_id) do nothing;
  end if;
  return s.id;
end;
$$;

-- ── 3 · Evidence follows its assessment ──────────────────────────────────

alter table public.evidence drop constraint evidence_assessment_fk;
alter table public.evidence add constraint evidence_assessment_fk
  foreign key (assessment_id) references public.assessment_sessions (id) on delete cascade;

create function public.forget_participant_evidence() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.athlete_id is not null then
    delete from public.evidence where assessment_id = old.session_id and athlete_id = old.athlete_id;
  end if;
  return old;
end;
$$;

create trigger assessment_participants_forget after delete on public.assessment_participants
for each row execute function public.forget_participant_evidence();

-- ── 4 · Keeping a guest's results in an existing account ─────────────────

-- A guest account becomes a full one by adding a sign-in to it; nothing moves.
-- This is for the other case: the athlete already has an account. The guest
-- asks for a code, signs in to their own account, and hands the code over.
create table public.guest_claims (
  code text primary key default replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
  guest_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);

-- No policies: the table is reached through the two functions below only.
alter table public.guest_claims enable row level security;

create function public.start_claim() returns text
language plpgsql security definer set search_path = public as $$
declare
  c text;
begin
  if auth.uid() is null or not coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'only a guest profile can be handed over';
  end if;
  delete from public.guest_claims where guest_id = auth.uid() or created_at < now() - interval '1 hour';
  insert into public.guest_claims (guest_id) values (auth.uid()) returning code into c;
  return c;
end;
$$;

create function public.finish_claim(claim text) returns integer
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  g uuid;
  moved integer;
begin
  if me is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'sign in to your own account first';
  end if;
  select guest_id into g from public.guest_claims where code = claim and created_at > now() - interval '1 hour';
  if g is null or g = me then
    raise exception 'this hand-over code is not valid';
  end if;

  -- Where both took part in the same session, the account's own entry stands.
  update public.assessment_participants p set athlete_id = me
  where p.athlete_id = g
    and not exists (select 1 from public.assessment_participants x where x.session_id = p.session_id and x.athlete_id = me);
  get diagnostics moved = row_count;

  update public.evidence e set athlete_id = me
  where e.athlete_id = g
    and (e.assessment_id is null or not exists (
      select 1 from public.assessment_participants x where x.session_id = e.assessment_id and x.athlete_id = g));

  insert into public.course_enrollments (course_id, athlete_id, status, joined_at)
  select course_id, me, status, joined_at from public.course_enrollments where athlete_id = g
  on conflict (course_id, athlete_id) do nothing;
  delete from public.course_enrollments where athlete_id = g;

  update public.workout_logs set athlete_id = me where athlete_id = g;
  insert into public.athlete_goals (athlete_id, skill_id, created_at)
  select me, skill_id, created_at from public.athlete_goals where athlete_id = g
  on conflict (athlete_id, skill_id) do nothing;

  delete from public.guest_claims where guest_id = g;
  return moved;
end;
$$;

-- ── 5 · Live updates ─────────────────────────────────────────────────────

-- Supabase Realtime sends a change only to those the row-level rules let read
-- it. Skipped where the publication does not exist (a plain Postgres).
do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array['assessment_sessions', 'assessment_participants', 'assessment_results', 'evidence', 'course_enrollments', 'feedback'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end;
$$;

-- ── Grants ───────────────────────────────────────────────────────────────

revoke all on public.guest_claims from anon, authenticated;
grant execute on function public.peek_invite(text) to anon, authenticated;
grant execute on function public.join_assessment(text, text), public.start_claim(), public.finish_claim(text) to authenticated;
revoke execute on function public.start_claim(), public.finish_claim(text) from anon;
revoke execute on function public.forget_participant_evidence() from anon, authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0007_coach_access.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · coaching by approval
--
-- Being a coach is granted, not chosen: an athlete asks, an admin approves.
-- (Coaching will be a paid role; until then it is simply by invitation.)
--   1. Nobody gives themselves the coach role. Only an admin, or the SQL editor.
--   2. An athlete asks once, with an optional note; the request is theirs to see.
--   3. An admin sees every request and approves or declines it in one step.
--
-- Run once, after 0006.

-- ── 1 · The role is protected ────────────────────────────────────────────

-- Replaces the version from 0001, which protected only 'admin'. An upsert of
-- an existing profile arrives as an insert first, so "already had it" is read
-- from the stored row in both cases.
create or replace function public.protect_profile_roles() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  had public.app_role[];
  r public.app_role;
begin
  if auth.uid() is null then
    return new; -- the SQL editor, the service role, and sign-up itself
  end if;
  select roles into had from public.profiles where id = new.id;
  had := coalesce(had, '{athlete}');
  foreach r in array new.roles loop
    if r <> 'athlete' and not (r = any (had)) and not public.has_role('admin') then
      raise exception 'the % role is granted by an admin', r;
    end if;
  end loop;
  return new;
end;
$$;

-- ── 2 · Asking ───────────────────────────────────────────────────────────

create table public.coach_requests (
  athlete_id uuid primary key references public.profiles (id) on delete cascade,
  note text check (note is null or length(note) <= 500),
  status text not null default 'pending' check (status in ('pending', 'approved', 'declined')),
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  decided_by uuid references public.profiles (id) on delete set null
);

alter table public.coach_requests enable row level security;

-- Your own request, and every request for an admin. Changes go through the functions below.
create policy coach_requests_read on public.coach_requests for select to authenticated
  using (athlete_id = auth.uid() or public.has_role('admin'));

-- Ask, or ask again after a decline. A guest cannot: there would be nobody to coach as.
create function public.request_coach(note text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'sign in with an account to ask for coach access';
  end if;
  if public.has_role('coach') then
    return;
  end if;
  insert into public.coach_requests (athlete_id, note) values (auth.uid(), nullif(btrim(note), ''))
  on conflict (athlete_id) do update set note = excluded.note, status = 'pending', created_at = now(), decided_at = null, decided_by = null
  where coach_requests.status <> 'pending';
end;
$$;

create function public.withdraw_coach_request() returns void
language sql security definer set search_path = public as $$
  delete from public.coach_requests where athlete_id = auth.uid() and status = 'pending';
$$;

-- ── 3 · Deciding ─────────────────────────────────────────────────────────

create function public.decide_coach(athlete uuid, approve boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.has_role('admin') then
    raise exception 'only an admin decides coach access';
  end if;
  update public.coach_requests set status = case when approve then 'approved' else 'declined' end, decided_at = now(), decided_by = auth.uid()
  where athlete_id = athlete;
  if approve then
    update public.profiles set roles = array(select distinct unnest(roles || '{coach}'::public.app_role[])) where id = athlete;
  end if;
end;
$$;

-- Taking coaching away. Their courses and sessions stay; they can no longer make new ones.
create function public.revoke_coach(athlete uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.has_role('admin') then
    raise exception 'only an admin decides coach access';
  end if;
  update public.profiles set roles = array_remove(roles, 'coach') where id = athlete;
end;
$$;

-- ── Grants ───────────────────────────────────────────────────────────────

revoke insert, update, delete on public.coach_requests from anon, authenticated;
grant select on public.coach_requests to authenticated;
grant execute on function public.request_coach(text), public.withdraw_coach_request(), public.decide_coach(uuid, boolean), public.revoke_coach(uuid) to authenticated;
revoke execute on function public.request_coach(text), public.withdraw_coach_request(), public.decide_coach(uuid, boolean), public.revoke_coach(uuid) from anon;

-- ── Making yourself the owner (run by hand, once, after your first sign-in) ──
--
--   update public.profiles set roles = '{athlete,coach,admin}'
--   where id = (select id from auth.users where email = 'YOUR-EMAIL');


-- ════════════════════════════════════════════════════════════════════════
-- 0008_course_weeks_and_station_mode.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · structured courses and station-based assessments
--
--   1. A course week can be an assessment week (the baseline at the start, the
--      re-test at the end) and can name the capability it focuses on.
--   2. An exercise in a course can be marked as part of the week's primary
--      focus, as opposed to support work.
--   3. An assessment runs guided (each station walks through its benchmarks
--      in order) or by stations (athletes choose the variations that fit
--      them), and the class can be split into rotation groups.
--
-- Only adds columns, each with a default. Run once, after 0007.

alter table public.course_weeks add column kind text not null default 'training'
  check (kind in ('training', 'baseline', 'retest'));
alter table public.course_weeks add column focus text
  check (focus is null or focus in ('handstand', 'pull', 'push', 'core', 'legs', 'mobility', 'full'));

alter table public.course_blocks add column is_primary boolean not null default false;

alter table public.assessment_sessions add column mode text not null default 'guided'
  check (mode in ('guided', 'stations'));
alter table public.assessment_sessions add column groups smallint not null default 1
  check (groups between 1 and 12);

-- Unset: placed by joining order. Set by the coach to move someone to another group.
alter table public.assessment_participants add column group_no smallint
  check (group_no is null or group_no between 0 and 11);


-- ════════════════════════════════════════════════════════════════════════
-- 0009_visual_content.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · demonstrations, workout videos and theme settings
--
-- Content that belongs to everyone and is managed by an admin:
--   1. Demonstrations of an exercise: an animation (a recipe the app renders:
--      which character, motion and camera) or a recorded video. Every version
--      is kept; athletes see a version only once it is published, and one
--      slot of one exercise has at most one published version.
--   2. Complete workout videos, filmed outside Aura.
--   3. App-wide settings, such as the default Aura theme.
--
-- Anyone reads what is published, signed in or not. Only an admin writes.
-- Only adds tables. Run once, after 0008.

-- ── 1 · Demonstrations ───────────────────────────────────────────────────

create table public.demo_assets (
  id uuid primary key default gen_random_uuid(),
  exercise_id text not null references public.exercises (id) on delete cascade,
  kind text not null check (kind in ('animation', 'video')),
  -- What it is within the exercise: 'male', 'female', 'instructor', 'instructor:<angle or variation>'.
  slot text not null check (length(slot) between 1 and 80),
  version int not null check (version >= 1),
  status text not null default 'draft'
    check (status in ('draft', 'pending', 'approved', 'published', 'needs_correction', 'archived')),
  title text not null default '',
  description text not null default '',
  -- The animation recipe, or where the video is.
  recipe jsonb not null default '{}',
  -- Correction notes, kept with the version they were written on.
  notes jsonb not null default '[]',
  replaces uuid references public.demo_assets (id) on delete set null,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  reviewed_at timestamptz,
  published_at timestamptz,
  unique (exercise_id, kind, slot, version)
);

create unique index demo_assets_one_published on public.demo_assets (exercise_id, kind, slot) where status = 'published';
create index demo_assets_by_exercise on public.demo_assets (exercise_id);

alter table public.demo_assets enable row level security;

create policy demo_assets_public on public.demo_assets for select to anon
  using (status = 'published');
create policy demo_assets_read on public.demo_assets for select to authenticated
  using (status = 'published' or public.has_role('admin'));
create policy demo_assets_write on public.demo_assets for all to authenticated
  using (public.has_role('admin')) with check (public.has_role('admin'));

-- ── 2 · Workout videos ───────────────────────────────────────────────────

create table public.workout_videos (
  id uuid primary key default gen_random_uuid(),
  title text not null default '',
  description text not null default '',
  focus text not null default 'full'
    check (focus in ('handstand', 'pull', 'push', 'core', 'legs', 'mobility', 'full')),
  level text not null default 'all' check (level in ('beginner', 'intermediate', 'advanced', 'all')),
  minutes int not null default 0 check (minutes >= 0),
  equipment text[] not null default '{}',
  exercise_ids text[] not null default '{}',
  course_id uuid references public.courses (id) on delete set null,
  -- Where the video is: an upload in storage or a link to a host.
  video jsonb,
  -- Moments in the video: introduction, work and rest, each optionally naming an exercise.
  chapters jsonb not null default '[]',
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz
);

alter table public.workout_videos enable row level security;

create policy workout_videos_public on public.workout_videos for select to anon
  using (status = 'published');
create policy workout_videos_read on public.workout_videos for select to authenticated
  using (status = 'published' or public.has_role('admin'));
create policy workout_videos_write on public.workout_videos for all to authenticated
  using (public.has_role('admin')) with check (public.has_role('admin'));

-- ── 3 · Settings ─────────────────────────────────────────────────────────

create table public.app_settings (
  key text primary key check (length(key) between 1 and 60),
  value jsonb not null,
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now()
);

alter table public.app_settings enable row level security;

create policy app_settings_read on public.app_settings for select to anon, authenticated using (true);
create policy app_settings_write on public.app_settings for all to authenticated
  using (public.has_role('admin')) with check (public.has_role('admin'));

-- ── Grants ───────────────────────────────────────────────────────────────

grant select on public.demo_assets, public.workout_videos, public.app_settings to anon;
grant select, insert, update, delete on public.demo_assets, public.workout_videos, public.app_settings to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0010_start_over.sql
-- ════════════════════════════════════════════════════════════════════════

-- Aura · starting over
--
-- An athlete can erase their own training record and go back to the welcome
-- questions, without losing the account. Some of what has to go is not theirs
-- to delete row by row (a result a coach verified, the evidence an assessment
-- produced), so it is one function, run as the athlete and for the athlete only.
--
-- Erased: results (every tier), workouts, goals, assessments taken alone, and
-- the athlete's answers in other people's assessments.
-- Kept: the account, its name and its roles, courses the athlete coaches and
-- the assessments they run for others, enrolments, who they follow.
--
-- Adds one function. Run once, after 0009.

create function public.start_over() returns void
language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'sign in to start over';
  end if;
  -- Answers in other people's assessments: the results, and the evidence drawn from them, go with the row.
  delete from public.assessment_participants where athlete_id = me;
  -- Assessments taken alone.
  delete from public.assessment_sessions where owner_id = me and solo;
  delete from public.evidence where athlete_id = me;
  delete from public.workout_logs where athlete_id = me;
  delete from public.athlete_goals where athlete_id = me;
  -- No handle is how the app knows the welcome questions have not been answered.
  update public.profiles set handle = null, bio = '' where id = me;
end;
$$;

revoke all on function public.start_over() from public, anon;
grant execute on function public.start_over() to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0011_personal_style.sql
-- ════════════════════════════════════════════════════════════════════════

-- Personalization: an athlete's theme, character and Aura form, more about
-- themselves, and three more things they can choose to share.
--
-- Everything is added to the athlete's own identity row, so nothing that
-- exists is moved or rewritten. All of it is presentation: no rating reads it.

alter table public.athlete_identity
  -- More about the athlete
  add column country text check (country is null or length(country) <= 60),
  add column interests text[] not null default '{}',
  -- Who sees the character they chose, their ratings, and their favourite disciplines
  add column style_audience public.audience not null default 'everyone',
  -- Results stay private unless the athlete opens them: this is the rule that was in force before.
  add column ratings_audience public.audience not null default 'me',
  add column interests_audience public.audience not null default 'everyone',
  -- Personal style
  add column theme text not null default 'dark' check (theme in ('dark', 'light', 'power', 'iron')),
  -- Which of the two characters is theirs
  add column persona text check (persona in ('male', 'female')),
  add column form_aura text check (length(form_aura) <= 40),
  add column form_power text check (length(form_power) <= 40),
  add column form_iron text check (length(form_iron) <= 40),
  add column finish_aura text check (length(finish_aura) <= 40),
  add column finish_power text check (length(finish_power) <= 40),
  add column finish_iron text check (length(finish_iron) <= 40),
  add column intensity smallint not null default 60 check (intensity between 0 and 100),
  add column show_muscles boolean not null default true,
  -- When each step of personalization was completed
  add column themed_at timestamptz,
  add column persona_at timestamptz,
  add column about_at timestamptz,
  add column sharing_at timestamptz;

-- ── Sharing ratings ──────────────────────────────────────────────────────

-- Has `owner` opened their results to the caller? A hidden profile shares nothing.
create function public.shares_ratings(owner uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.can_see_profile(owner) and public.audience_allows(
    coalesce((select ratings_audience from public.athlete_identity where athlete_id = owner), 'me'), owner);
$$;

-- Results were readable by the athlete and their coach. Now also by whoever the athlete chose.
drop policy evidence_read on public.evidence;
create policy evidence_read on public.evidence for select to authenticated
  using (athlete_id = auth.uid() or public.coaches_athlete(athlete_id) or public.shares_ratings(athlete_id));

-- ── What others may see of the new parts ─────────────────────────────────

-- An athlete's chosen look, as far as the caller is allowed to see it. Hidden: no row.
create function public.style_of(p uuid)
returns table (theme text, persona text, form_aura text, form_power text, form_iron text, finish_aura text, finish_power text, finish_iron text)
language sql stable security definer set search_path = public as $$
  select i.theme, i.persona, i.form_aura, i.form_power, i.form_iron, i.finish_aura, i.finish_power, i.finish_iron
  from public.athlete_identity i
  where i.athlete_id = p and public.can_see_profile(p) and public.audience_allows(i.style_audience, p);
$$;

-- Country and favourite disciplines, each under its own audience. Hidden parts come back empty.
create function public.about_of(p uuid)
returns table (country text, interests text[])
language sql stable security definer set search_path = public as $$
  select
    case when public.audience_allows(i.base_audience, p) then i.country end,
    case when public.audience_allows(i.interests_audience, p) then i.interests else '{}' end
  from public.athlete_identity i
  where i.athlete_id = p and public.can_see_profile(p);
$$;

revoke execute on function public.shares_ratings(uuid), public.style_of(uuid), public.about_of(uuid) from public, anon;
grant execute on function public.shares_ratings(uuid), public.style_of(uuid), public.about_of(uuid) to authenticated;


-- ════════════════════════════════════════════════════════════════════════
-- 0012_ratings_open.sql
-- ════════════════════════════════════════════════════════════════════════

-- An athlete's Aura and ratings are open to other athletes unless they close
-- them. 0011 started them at "only me"; the owner decided the other way round.
--
-- Athletes who have not been through the sharing step have chosen nothing
-- yet, so the new starting point is theirs too. A choice already made is
-- kept. A hidden profile still shares nothing (shares_ratings, 0011).
--
-- Safe to run twice: the second run finds the new default and does nothing,
-- so it can never reopen ratings someone closed afterwards.

do $$
begin
  if (select column_default from information_schema.columns
      where table_schema = 'public' and table_name = 'athlete_identity' and column_name = 'ratings_audience') like '''me''%' then
    update public.athlete_identity set ratings_audience = 'everyone' where ratings_audience = 'me' and sharing_at is null;
    alter table public.athlete_identity alter column ratings_audience set default 'everyone';
  end if;
end $$;


-- ════════════════════════════════════════════════════════════════════════
-- 0013_more_themes.sql
-- ════════════════════════════════════════════════════════════════════════

-- A fifth theme (Goku Light), and room for the ones after it.
--
-- 0011 listed the four theme ids in a check on athlete_identity.theme, so
-- every new theme needed a database step. A theme is presentation and the
-- app knows which ids exist (an id it does not know is shown as the original
-- theme), so the database now only checks that the value looks like an id.
--
-- Nothing stored is changed. Safe to run twice.

alter table public.athlete_identity drop constraint if exists athlete_identity_theme_check;
alter table public.athlete_identity add constraint athlete_identity_theme_check check (theme ~ '^[a-z][a-z-]{1,23}$');


-- ════════════════════════════════════════════════════════════════════════
-- 0014_coach_sees_training.sql
-- ════════════════════════════════════════════════════════════════════════

-- A coach sees all the training of the athletes in their courses.
--
-- Until now a coach could read a student's results (evidence, ratings,
-- assessments) but only the workouts logged inside the coach's own course.
-- Quick sessions, sessions toward a goal, and the starter sessions of a
-- course's first week were invisible to them, so a coach could not see
-- whether a student trains or grows.
--
-- From here on, while an athlete is enrolled in one of a coach's courses, the
-- coach reads every workout they log, with what was assigned and what they
-- actually did. This is not something the athlete can switch off: it is the
-- point of having a coach, and it is what Aura's privacy policy already says
-- ("your training and results while you are enrolled in one of their courses").
-- It ends when the athlete leaves the course; logs from within the course stay
-- readable to its coach, as before.
--
-- Only reading changes. Nobody but the athlete can add, change or delete a log.
-- Safe to run twice.

create or replace function public.can_read_log(l uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.workout_logs wl
    where wl.id = l and (
      wl.athlete_id = auth.uid()
      or public.coaches_athlete(wl.athlete_id)
      or (wl.course_id is not null and public.coaches_course(wl.course_id))
    )
  );
$$;

drop policy if exists logs_read on public.workout_logs;
create policy logs_read on public.workout_logs for select to authenticated
  using (athlete_id = auth.uid() or public.coaches_athlete(athlete_id) or (course_id is not null and public.coaches_course(course_id)));

-- And the coach can say something about any of those sessions, not only the course's own.
drop policy if exists feedback_insert on public.feedback;
create policy feedback_insert on public.feedback for insert to authenticated
  with check (
    coach_id = auth.uid()
    and exists (
      select 1 from public.workout_logs wl
      where wl.id = log_id and wl.athlete_id = feedback.athlete_id
        and (public.coaches_athlete(wl.athlete_id) or (wl.course_id is not null and public.coaches_course(wl.course_id)))
    )
  );


-- ════════════════════════════════════════════════════════════════════════
-- 0015_block_name_and_unit.sql
-- ════════════════════════════════════════════════════════════════════════

-- A coach names a part of a session and chooses its unit.
--
-- An exercise in a course was always written in the exercise's own unit
-- (repetitions, or seconds for a hold) and shown by the exercise's name. A
-- coach may now write it their own way: "Wrist preparation + warm up", one
-- round of 60 seconds. `title` is that name; `metric` is the unit, set only
-- when it differs from the exercise's own. A workout logged from such a block
-- keeps both, so the coach reads it as it was written.
--
-- Work in another unit than the exercise's own is never a record: the app
-- does not offer it as a result, so no rating changes because of this.
--
-- Two new columns on two tables, nothing else. Safe to run twice.

alter table public.course_blocks
  add column if not exists title text check (title is null or char_length(title) <= 80),
  add column if not exists metric text check (metric is null or metric in ('reps', 'hold'));

alter table public.workout_log_entries
  add column if not exists title text check (title is null or char_length(title) <= 80),
  add column if not exists metric text check (metric is null or metric in ('reps', 'hold'));


